CREATE TABLE IF NOT EXISTS servers (id VARCHAR(80) PRIMARY KEY, name VARCHAR(150) NOT NULL, last_seen DATETIME NULL);
CREATE TABLE IF NOT EXISTS monitored_bots (id BIGINT AUTO_INCREMENT PRIMARY KEY, server_id VARCHAR(80) NOT NULL, service VARCHAR(160) NOT NULL, display_name VARCHAR(160) NOT NULL, category VARCHAR(80) NOT NULL DEFAULT 'Other Bots', enabled BOOLEAN NOT NULL DEFAULT TRUE, status VARCHAR(20) NOT NULL DEFAULT 'unknown', updated_at DATETIME NULL, UNIQUE KEY uq_bot (server_id,service));
CREATE TABLE IF NOT EXISTS events (id BIGINT AUTO_INCREMENT PRIMARY KEY, bot_id BIGINT NOT NULL, old_status VARCHAR(20), new_status VARCHAR(20) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX (created_at));
CREATE TABLE IF NOT EXISTS settings (name VARCHAR(80) PRIMARY KEY, value TEXT NOT NULL);